package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class TwoStepFractionStoriesTest {
 @Test public void twoDistinctOperationsIgnoreSavedKeys(){for(int extra:new int[]{0,3}){Question q=TwoStepFractionStories.make(10,2,5,extra);q.answers[0]="999";q.expression="999";String expected=extra==0?"6/1":"7/1";assertTrue(new Checker().check(q,List.of(),List.of(expected)).correct());assertFalse(new Checker().check(q,List.of(),List.of("4/1")).correct());HelpPlan h=HelpPlan.forQuestion(q);assertEquals(5,h.size());assertFalse(h.canTransfer());assertTrue(h.step(3).accepts("4"));assertTrue(h.step(4).accepts(expected));assertTrue(FractionInput.defaultFraction(q));}}
 @Test public void nonintegerMeasuredResultsKeepUnitsAndEquivalentAnswers(){Question q=TwoStepFractionStories.make(5,2,3,0);assertTrue(new Checker().check(q,List.of(),List.of("10/6")).correct());assertFalse(new Checker().check(q,List.of(),List.of("10/3")).correct());assertEquals(1,TwoStepFractionStories.errorPart(q,"6/3"));assertEquals(2,TwoStepFractionStories.errorPart(q,"5/4"));assertNull(TwoStepFractionStories.read(new Question(q.skillId,q.prompt.replace(" m"," L"),"","0")));}
 @Test public void normalNaSixFreshSupplyHasBothContextsAndFractionalResults(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(TwoStepFractionStories.ID,6));var limits=GlobalCurriculum.limits(pack.id,TwoStepFractionStories.ID,6);Generator g=new Generator(new Random(285));List<String> recent=new ArrayList<>();boolean remainder=false,added=false,noninteger=false;for(int i=0;i<180;i++){Question q=g.next(TwoStepFractionStories.ID,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=TwoStepFractionStories.read(q);assertNotNull(v);remainder|=v.remaining();added|=!v.remaining();noninteger|=!TwoStepFractionStories.answer(v).d.equals(java.math.BigInteger.ONE);assertTrue(limits.allows(q));assertTrue(new Checker().check(q,List.of(),List.of(TwoStepFractionStories.answer(v).n+"/"+TwoStepFractionStories.answer(v).d)).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertTrue(remainder);assertTrue(added);assertTrue(noninteger);}
}
